SITE_APP_PATHS = ("/live", "/news", "/open", "/people", "/posters", "/more", "/app", "/login")


def dash_signed_in_html(prm: dict) -> str:
    return {"1": DASHBOARD_HTML, "2": DASHBOARD_HTML_V2, "3": DASHBOARD_HTML_V3,
            "4": DASHBOARD_HTML_V4}.get(prm["v"] or "4", DASHBOARD_HTML_V4)


async def dash_index(request):
    from aiohttp import web
    ip = dash_client_ip(request)
    key = request.query.get("key")
    path = request.path or "/"
    if key is not None:
        prm, err = dash_gate(web, request)
        if err is not None:
            return err
        dash_take_key(key)
        # good key: remember it in a cookie and take it out of the address bar (and history)
        go = "/" if path in ("/", "/login", "/app") else path
        q = {k: v for k, v in (("v", prm["v"]), ("guild", request.query.get("guild"))) if v}
        resp = web.Response(status=303, headers={"Location": go + ("?" + _dash_urlencode(q) if q else "")})
        stay = request.query.get("stay") != "0"
        ck = dict(path="/", httponly=True, secure=True, samesite="Lax")
        if stay:
            ck["max_age"] = DASH_COOKIE_AGE
        resp.set_cookie(DASH_COOKIE, dash_cookie_value(), **ck)
        resp.set_cookie(DASH_DEV_COOKIE, dash_note_login(request, "link"), **ck)
        return resp
    if dash_member_blocked(request):
        return dash_page(web, 403, "Dashboard closed",
                         "You were removed from the server, so this dashboard is closed.")
    if not dash_authed(request):
        if not dash_rate(ip, "bad", *DASH_BAD_KEYS, count=False):
            return dash_error(web, request, 429)
        return dash_html(web, dash_paint_look(SITE_HTML))
    if path == "/login":
        return web.Response(status=303, headers={"Location": "/"})
    prm = dash_params(request)
    if prm is None:
        return dash_error(web, request, 400)
    return dash_html(web, dash_staff_inject(dash_paint_look(dash_signed_in_html(prm)), request))


async def dash_login_post(request):
    """Sign-in form: POST so the access key is not stripped the way a GET password field often is."""
    from aiohttp import web
    ip = dash_client_ip(request)
    form = await _req_form(request)
    key = str(form.get("key") or "")
    if not dash_rate(ip, "bad", *DASH_BAD_KEYS, count=False):
        return dash_error(web, request, 429)
    if not dash_key_ok(key):
        dash_rate(ip, "bad", *DASH_BAD_KEYS)
        return dash_error(web, request, 403)
    dash_take_key(key)
    resp = web.Response(status=303, headers={"Location": "/"})
    stay = str(form.get("stay") or "1") != "0"
    ck = dict(path="/", httponly=True, secure=True, samesite="Lax")
    if stay:
        ck["max_age"] = DASH_COOKIE_AGE
    resp.set_cookie(DASH_COOKIE, dash_cookie_value(), **ck)
    resp.set_cookie(DASH_DEV_COOKIE, dash_note_login(request, "form"), **ck)
    return resp


async def dash_api_data(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    gid = prm["guild"]
    lite = str(request.query.get("lite") or "") == "1"
    d = dashboard_data(gid)
    d["needs"] = dash_needs(gid)
    if lite:
        d.setdefault("ticker", [])
        d.setdefault("games", [])
    else:
        d.update(await dash_live(gid))
    d["updated"] = datetime.now(TZ).strftime("%-I:%M %p")
    acct = acct_from_request(request)
    d["me"] = str(acct.get("discord_id") or "") if acct else ""
    DASH_ANSWERED["at"] = now_iso()
    return web.json_response(d)


async def dash_api_log(request):
    """Log a slip from the dashboard. Same confirm rules as Discord: never hidden, never a lock."""
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    ip = dash_client_ip(request)
    if not dash_rate(ip, "log", 8, 60):
        return dash_error(web, request, 429)
    body = await _req_json(request)
    who = clip(str(body.get("who") or ""), 40)
    what = clip(str(body.get("what") or ""), 200)
    plat = clip(str(body.get("platform") or "Other"), 24) or "Other"
    cost = as_amount(body.get("cost")) or 0.0
    payout = as_amount(body.get("payout")) or 0.0
    if not who or not what:
        return web.json_response({"ok": False, "error": "Need a name and a pick."}, status=400)
    low = what.lower()
    if "sure thing" in low or "sure-thing" in low or re.search(r"\block\b", low):
        return web.json_response({"ok": False, "error": "Log the play. Leave out lock language."}, status=400)
    acct = acct_from_request(request)
    bettor_id = None
    if acct:
        bettor_id = acct.get("discord_id")
        if acct.get("name"):
            who = clip(str(acct.get("name")), 40)
    pid = insert_pick(guild_id=prm["guild"], bettor_key=norm_name(who), bettor_name=who,
                      bettor_id=bettor_id, logged_by=0, platform=plat, sport=None,
                      description=what, legs=what, cost=float(cost), payout=float(payout))
    _DASH_LIVE_CACHE.pop(prm["guild"], None)
    try:
        staff_log_add(prm["guild"], "ok", f"Logged slip #{pid} from the site", who)
    except Exception:
        pass
    return web.json_response({"ok": True, "id": pid})


async def dash_avatar_img(request):
    """A crew member's Discord picture, circled. Initials when Discord has no photo."""
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    uid_s = request.match_info.get("uid", "")
    if not uid_s.isdigit():
        return dash_error(web, request, 404)
    uid = int(uid_s)
    user = await known_user(bot, uid)
    raw = await avatar_bytes(user) if user else None
    name = ""
    if user is not None:
        name = str(getattr(user, "display_name", None) or getattr(user, "name", None) or "")
    if not name:
        name = uid_s

    def draw() -> bytes:
        img = _avatar(raw, 128, name, -1)
        buf = io.BytesIO()
        img.save(buf, format="PNG")
        return buf.getvalue()

    try:
        png = await asyncio.to_thread(draw)
    except Exception:
        log.exception("Avatar image failed")
        return dash_error(web, request, 404)
    return web.Response(body=png, content_type="image/png", headers={"Cache-Control": "private, max-age=300"})


async def dash_api_dm(request):
    """A mod, owner, or developer opts in to a Discord profile link on their card."""
